//! An ingress diagram generated by a slide generator (D-058): a wide bar among wide zones spans them, links
//! into a card whose single arrow goes back up a stack keep their own side, and a service pushed
//! along its row brings its pods with it.

use skemo_engine::{Options, from_source};

fn build(name: &str) -> skemo_engine::Diagram {
    let (src, css) = match name {
        "ingress" => (
            include_str!("data/ingress.skemo"),
            include_str!("data/ingress.css"),
        ),
        _ => (
            include_str!("data/ingress-rows.skemo"),
            include_str!("data/ingress-rows.css"),
        ),
    };
    let opts = Options {
        css: vec![css.to_string()],
        ..Options::default()
    };
    from_source(src, &opts).unwrap().0
}

#[test]
fn a_wide_bar_among_wide_zones_spans_them() {
    let d = build("ingress");
    let (bus, apps) = (d.boxes["bus"], d.boxes["apps"]);
    assert!(
        bus.x <= apps.x + 0.5 && bus.right() >= apps.right() - 0.5,
        "{bus:?} {apps:?}"
    );
}

#[test]
fn a_link_enters_by_the_side_facing_it() {
    let d = build("ingress");
    for (id, to) in [("ia->c1", "c1"), ("ib->c2", "c2")] {
        let r = &d.routes[id];
        let end = r.last().unwrap();
        assert!(
            (end.1 - d.boxes[to].y).abs() < 0.5,
            "{id} enters by the top: {r:?}"
        );
        assert!(r.len() <= 4, "{id} goes straight or with one step: {r:?}");
    }
}

#[test]
fn services_sit_in_the_middle_of_their_pods() {
    let d = build("ingress-rows");
    let mid = |id: &str| d.boxes[id].x + d.boxes[id].w / 2.0;
    for (svc, pods) in [("sa", ["a1", "a2"]), ("sb", ["b1", "b2"])] {
        let m = f64::midpoint(mid(pods[0]), mid(pods[1]));
        assert!((mid(svc) - m).abs() < 1.0, "{svc}: {} vs {m}", mid(svc));
    }
}

#[test]
fn two_sites_stand_in_mirror_round_their_ingress() {
    let d = build("ingress-rows");
    let mid = |id: &str| d.boxes[id].x + d.boxes[id].w / 2.0;
    let axis = mid("ic");
    for (a, b) in [
        ("a1", "b2"),
        ("a2", "b1"),
        ("sa", "sb"),
        ("ia", "ib"),
        ("c1", "c2"),
    ] {
        assert!(
            // cards stand on whole pixels: 1 px at most
            ((axis - mid(a)) - (mid(b) - axis)).abs() <= 1.0 + 1e-9,
            "{a}/{b}: {} vs {}",
            axis - mid(a),
            mid(b) - axis
        );
    }
}
